    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint d, uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(address(this).balance >= d);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCtr = address(this).balance;
        require(beforeBal >= d);
        require(a <= beforeBal);
        c.Collect(a); if (__ESBMC_reverted()) return;
        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        assert(afterBal == beforeBal - a && address(this).balance == beforeCtr + a);
    }
    receive() external payable {}
