import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 d, uint256 a) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeCtr = address(this).balance;
        vm.assume(beforeBal >= d);
        vm.assume(a <= beforeBal);
        try c.Collect(a) {} catch { return; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(afterBal == beforeBal - a && address(this).balance == beforeCtr + a);
    }

    function testFuzz_run(uint256 d, uint256 a) public {
        _run(d, a);
    }

    receive() external payable {}
}
